const artwork=n=>globalThis.RAMY_ARTWORK?.[n]?`<img class="section-art" src="${RAMY_ARTWORK[n]}" alt="" aria-hidden="true" width="96" height="96">`:'';
const intro=(section,title,copy,badge='')=>`<div class="intro"><div class="intro-copy"><h1>${E(title)}</h1>${copy?`<p>${E(copy)}</p>`:''}${badge?`<span class="badge">${E(badge)}</span>`:''}</div>${artwork(section)}</div>`;
const statusLabel=s=>({proposal:'Proposed',booked:'Booked',cancelled:'Cancelled',matured:'Matured'}[s]||s);
const scheduleLabel=s=>({one_off:'One-off',monthly:'Monthly',weekly:'Weekly',flexible:'Flexible',existing:'Existing holding'}[s]||s);
